'use client';

import '../globals.css';
import { useEffect, useMemo, useState } from 'react';

type HistoryItem = {
  spot_id: number;
  score: number | null;
  answered_at: string;
  title: string | null;
  genre: string | null;
  description: string | null;
  lat: number | null;
  lng: number | null;
  image_path: string | null;
};

type MeResponse = { uuid: string };

type Hotel = {
  id: number | null;
  name: string | null;
  address: string | null;
  lat: number | null;
  lng: number | null;
  minCharge: number | null;
  reviewAverage: number | null;
  reviewCount: number | null;
  thumbnail: string | null;
  infoUrl: string | null;
  planUrl: string | null;
};

const API_BASE =
  process.env.NEXT_PUBLIC_API_BASE || 'http://localhost:3000';


const PAGE_SIZE = 5;

export default function HistoryPage() {
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [page, setPage] = useState(0);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // ホテル用
  const [hotels, setHotels] = useState<Hotel[]>([]);
  const [hotelsStatus, setHotelsStatus] = useState<string>('履歴を選択すると、周辺ホテルを検索します。');
  const [hotelsLoading, setHotelsLoading] = useState(false);

  // 初回ロード: /api/me → /api/history/:uuid
  useEffect(() => {
    (async () => {
      try {
        const meRes = await fetch(`${API_BASE}/api/me`, {
          credentials: 'include',
        });
        if (!meRes.ok) throw new Error('認証が必要です');
        const me: MeResponse = await meRes.json();

        const histRes = await fetch(
          `${API_BASE}/api/history/${encodeURIComponent(me.uuid)}`,
          { credentials: 'include' },
        );
        const data = await histRes.json();
        if (!data.success) throw new Error(data.error || '履歴の取得に失敗しました');

        const list: HistoryItem[] = data.history || [];
        setHistory(list);
        setPage(0);

        if (list.length > 0) {
          setSelectedIndex(0);
        } else {
          setSelectedIndex(null);
        }
      } catch (e: any) {
        setError(e.message ?? 'エラーが発生しました');
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  // ページング済みのリスト
  const pagedHistory = useMemo(() => {
    const start = page * PAGE_SIZE;
    return history.slice(start, start + PAGE_SIZE);
  }, [history, page]);

  const totalPages = Math.max(1, Math.ceil(history.length / PAGE_SIZE));

  // 今のページの先頭を選択する（ページ切り替え時など）
  useEffect(() => {
    if (!history.length) {
      setSelectedIndex(null);
      return;
    }

    const start = page * PAGE_SIZE;
    if (start >= history.length) {
      // ページが範囲外になった場合は最後のページに合わせる
      const lastPage = Math.max(0, Math.ceil(history.length / PAGE_SIZE) - 1);
      setPage(lastPage);
      const newStart = lastPage * PAGE_SIZE;
      setSelectedIndex(newStart);
      return;
    }

    if (selectedIndex == null || selectedIndex < start || selectedIndex >= start + PAGE_SIZE) {
      setSelectedIndex(start);
    }
  }, [history.length, page]);

  // 現在選択中の要素
  const selected = useMemo(
    () => (selectedIndex != null ? history[selectedIndex] : null),
    [history, selectedIndex],
  );

  // 選択変更時にホテル情報を読み込み
  useEffect(() => {
    if (!selected || selected.lat == null || selected.lng == null) {
      setHotels([]);
      if (!selected) {
        setHotelsStatus('履歴を選択すると、周辺ホテルを検索します。');
      } else {
        setHotelsStatus('このスポットには座標情報がないため、周辺ホテルを検索できません。');
      }
      setHotelsLoading(false);
      return;
    }

    (async () => {
      try {
        setHotelsLoading(true);
        setHotels([]);
        setHotelsStatus('周辺ホテルを検索しています...');

        const params = new URLSearchParams({
          lat: String(selected.lat),
          lng: String(selected.lng),
          radiusKm: '1.0',
          hits: '5',
        });

        const res = await fetch(
          `${API_BASE}/api/hotels_nearby_rakuten?${params.toString()}`,
          { credentials: 'include' },
        );
        const data = await res.json();

        if (!data.success || !Array.isArray(data.hotels) || data.hotels.length === 0) {
          setHotels([]);
          setHotelsStatus('周辺に表示できるホテルが見つかりませんでした。');
          return;
        }

        setHotels(
          data.hotels.map((h: any) => ({
            id: h.id ?? null,
            name: h.name ?? null,
            address: h.address ?? null,
            lat: h.lat ?? null,
            lng: h.lng ?? null,
            minCharge: h.minCharge ?? null,
            reviewAverage: h.reviewAverage ?? null,
            reviewCount: h.reviewCount ?? null,
            thumbnail:
              h.thumbnail ||
              h.imageUrl ||
              h.hotelImageUrl ||
              h.image ||
              (Array.isArray(h.imageUrls) ? h.imageUrls[0] : null),
            infoUrl: h.infoUrl ?? null,
            planUrl: h.planUrl ?? null,
          })),
        );

        setHotelsStatus(
          `検索範囲：約 ${data.radiusKm || '?'}km / ${data.count ?? data.hotels.length}件`,
        );
      } catch (e) {
        console.error('[hotels] error', e);
        setHotels([]);
        setHotelsStatus('ホテル情報の取得中にエラーが発生しました。');
      } finally {
        setHotelsLoading(false);
      }
    })();
  }, [selected?.spot_id]); // spot_id が変わったときに再検索

  if (loading) return <p>読み込み中...</p>;
  if (error) return <p>エラー: {error}</p>;

  return (
    <div className="history-layout">
      {/* 左：出題履歴リスト */}
      <div className="history-left">
        <button
          type="button"
          className="back-home-btn"
          onClick={() => {
            // 既存の /home に飛ばす（必要に応じて修正）
            window.location.href = '/home';
          }}
        >
          🏠 ホームに戻る
        </button>

        <h2>📜 出題履歴</h2>

        {history.length === 0 ? (
          <p>出題履歴がありません。</p>
        ) : (
          <>
            <ul className="history-list">
              {pagedHistory.map((item, i) => {
                const globalIndex = page * PAGE_SIZE + i;
                const isActive = globalIndex === selectedIndex;

                return (
                  <li
                    key={`${item.spot_id}-${globalIndex}`}
                    className={`history-item ${isActive ? 'active' : ''}`}
                    onClick={() => setSelectedIndex(globalIndex)}
                  >
                    <div className="history-item-title">
                      {item.title || '(タイトルなし)'}
                    </div>
                    <div className="history-item-sub">
                      スコア: {item.score ?? '-'} / 出題日時:{' '}
                      {formatDateTime(item.answered_at)}
                    </div>
                  </li>
                );
              })}
            </ul>

            {/* ページ送り */}
            <div className="history-pagination">
              <button
                type="button"
                onClick={() => setPage((p) => Math.max(0, p - 1))}
                disabled={page === 0}
              >
                ← 前の5件
              </button>
              <span className="history-page-info">
                {page + 1} / {totalPages}
              </span>
              <button
                type="button"
                onClick={() =>
                  setPage((p) =>
                    p + 1 >= totalPages ? p : p + 1,
                  )
                }
                disabled={page + 1 >= totalPages}
              >
                次の5件 →
              </button>
            </div>
          </>
        )}
      </div>

      {/* 右：詳細パネル */}
      <div className="history-right">
        <h2>🗺 選択した出題の詳細</h2>

        {!selected ? (
          <p>左の「出題履歴」から項目をクリックすると、ここに詳細が表示されます。</p>
        ) : (
          <div className="history-detail">
            {/* 画像 */}
            {selected.image_path && (
              <div className="detail-image-wrap">
                <img
                  src={selected.image_path}
                  alt={selected.title || 'スポット画像'}
                />
              </div>
            )}

            {/* テキスト情報 */}
            <h3>{selected.title || '(タイトルなし)'}</h3>
            <p className="detail-genre">
              ジャンル：{genreLabel(selected.genre)}
            </p>
            <p className="detail-description">
              {selected.description || '説明は登録されていません。'}
            </p>

            <div className="detail-meta">
              <span>スコア：{selected.score ?? '-'}</span>
              <span>出題日時：{formatDateTime(selected.answered_at)}</span>
            </div>

            {/* 周辺ホテル情報 */}
            <div className="detail-hotels">
              <h3>🏨 周辺ホテル</h3>
              <p className="hotels-status">
                {hotelsStatus}
                {hotelsLoading ? '（読み込み中…）' : ''}
              </p>
              <ul className="hotels-list">
                {hotels.map((h, idx) => (
                  <li key={`${h.id ?? 'hotel'}-${idx}`}>
                    <div className="hotel-card">
                      <div className="hotel-card-thumb">
                        {h.thumbnail && (
                          <img src={h.thumbnail} alt={h.name || 'ホテル画像'} />
                        )}
                      </div>
                      <div className="hotel-card-body">
                        <div className="hotel-card-name">
                          {h.name || '名称不明のホテル'}
                        </div>
                        {(h.minCharge || h.reviewAverage) && (
                          <div className="hotel-card-meta">
                            {h.minCharge && (
                              <span>最安値目安: {h.minCharge}円〜</span>
                            )}
                            {h.reviewAverage && (
                              <span>
                                評価: {h.reviewAverage}（{h.reviewCount ?? 0}
                                件）
                              </span>
                            )}
                          </div>
                        )}
                        <div className="hotel-card-actions">
                          <a
                            href={h.planUrl || h.infoUrl || '#'}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="hotel-link-btn"
                          >
                            詳細を見る
                          </a>
                        </div>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ===== util関数 =====

function formatDateTime(src: string | null) {
  if (!src) return '';
  const d = new Date(src);
  if (Number.isNaN(d.getTime())) return String(src);
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  const hh = String(d.getHours()).padStart(2, '0');
  const mi = String(d.getMinutes()).padStart(2, '0');
  return `${yyyy}/${mm}/${dd} ${hh}:${mi}`;
}

function genreLabel(g: string | null) {
  switch (g) {
    case 'historic':
      return '歴史・文化';
    case 'nature':
      return '自然';
    case 'city':
      return '都市・街並み';
    case 'culture':
      return '観光・文化';
    default:
      return g || '未分類';
  }
}
